"""Reloading a module: the environment its manifest asks for now is prepared first, and its contract is generated by
the module's own Python (the one it runs with), not the Host's."""

from __future__ import annotations

import asyncio
import json
import sys

from host.app import Host, HostConfig
from host.secrets import MemorySecrets
from tests.platform.harness import prepare


class Finished:
    returncode = 0

    async def communicate(self):
        return b"", None


def test_reload_prepares_the_new_environment_then_generates_the_contract_in_it(tmp_path, monkeypatch):
    async def scenario():
        root = prepare(tmp_path / "official", ("late",))
        host = Host(HostConfig(data_dir=tmp_path / "data", user_dir=tmp_path / "user", official_root=root,
                               secrets_store=MemorySecrets()))
        host.catalog.discover()
        assert host.catalog.get("late").python == sys.executable
        manifest = json.loads((root / "late" / "talyx.module.json").read_text())
        manifest["python"] = {"requirements": ["talyx-extra-fixture==1.0"]}
        (root / "late" / "talyx.module.json").write_text(json.dumps(manifest))
        steps = []

        async def prepare_environment(item):
            steps.append(("prepare", item.manifest["python"]["requirements"]))

        async def generate(program, *args, **options):
            steps.append(("generate", program))
            return Finished()

        async def nothing(*args):
            steps.append(("restart",))

        monkeypatch.setattr(asyncio, "create_subprocess_exec", generate)
        host.prepare_environment, host.stop_module = prepare_environment, nothing
        host.start_module = nothing
        await host.reload("late")
        python = str(host.catalog.environment_python(host.catalog.get("late")))
        assert python != sys.executable
        assert steps[:2] == [("prepare", ["talyx-extra-fixture==1.0"]), ("generate", python)]

    asyncio.run(scenario())
